"use client";

import AppShell from "@/components/Navbar";
import Link from "next/link";
import { useEffect, useState } from "react";
import { api } from "@/lib/api";
import { useRouter } from "next/navigation";

// ─────────────────────────────────────────────────────────────
// Types
// ─────────────────────────────────────────────────────────────
interface RoomType {
  id:   number;
  name: string;
}
interface Building {
  id: number;
  name: string;
}

interface FormData {
  room_number:  string;
  building:     string;
  capacity:     string;
  type_id:      string;
  is_available: boolean;
}

interface FieldErrors {
  room_number?: string;
  building?:    string;
  capacity?:    string;
  type_id?:     string;
}

// ─────────────────────────────────────────────────────────────
// Icons
// ─────────────────────────────────────────────────────────────
const Ico = ({ d, d2, size = 15 }: { d: string; d2?: string; size?: number }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none"
    stroke="currentColor" strokeWidth="1.85" strokeLinecap="round" strokeLinejoin="round">
    <path d={d} />{d2 && <path d={d2} />}
  </svg>
);

const IcoBack    = () => <Ico d="M19 12H5M12 19l-7-7 7-7" />;
const IcoRoom    = () => <Ico d="M3 9.5L12 3l9 6.5V20a1 1 0 01-1 1H4a1 1 0 01-1-1V9.5z" d2="M9 21V12h6v9" size={18} />;
const IcoUsers   = () => <Ico d="M17 21v-2a4 4 0 00-4-4H5a4 4 0 00-4 4v2" d2="M9 11a4 4 0 100-8 4 4 0 000 8z" size={18} />;
const IcoTag     = () => <Ico d="M20.59 13.41l-7.17 7.17a2 2 0 01-2.83 0L2 12V2h10l8.59 8.59a2 2 0 010 2.82zM7 7h.01" size={18} />;
const IcoBldg    = () => <Ico d="M6 22V4a2 2 0 012-2h8a2 2 0 012 2v18zM2 22h20M12 7h.01M12 11h.01M12 15h.01" size={18} />;
const IcoCheck   = () => <Ico d="M20 6L9 17l-5-5" size={16} />;
const IcoAlert   = () => <Ico d="M10.29 3.86L1.82 18a2 2 0 001.71 3h16.94a2 2 0 001.71-3L13.71 3.86a2 2 0 00-3.42 0zM12 9v4M12 17h.01" size={15} />;
const IcoInfo    = () => <Ico d="M12 2a10 10 0 100 20A10 10 0 0012 2zM12 16v-4M12 8h.01" size={14} />;

function Spinner() {
  return (
    <svg className="animate-spin" width="15" height="15" viewBox="0 0 24 24"
      fill="none" stroke="currentColor" strokeWidth="2.5">
      <path d="M12 2v4M12 18v4M4.93 4.93l2.83 2.83M16.24 16.24l2.83 2.83M2 12h4M18 12h4M4.93 19.07l2.83-2.83M16.24 7.76l2.83-2.83"
        strokeOpacity=".25" />
      <path d="M12 2v4" />
    </svg>
  );
}

// ─────────────────────────────────────────────────────────────
// Room type color chips
// ─────────────────────────────────────────────────────────────
const TYPE_STYLE: Record<string, { bg: string; color: string }> = {
  Lecture:    { bg: "#e8f5ee", color: "#1a7a3c" },
  Laboratory: { bg: "#eef2ff", color: "#3730a3" },
  Seminar:    { bg: "#fff8e6", color: "#92620a" },
  AVR:        { bg: "#f0f9ff", color: "#0369a1" },
  Gymnasium:  { bg: "#fdf4ff", color: "#6b21a8" },
};

// ─────────────────────────────────────────────────────────────
// Validation
// ─────────────────────────────────────────────────────────────
function validate(form: FormData): FieldErrors {
  const errs: FieldErrors = {};
  if (!form.room_number.trim())      errs.room_number = "Room number is required.";
  if (!form.building.trim())         errs.building    = "Building is required.";
  if (!form.capacity || Number(form.capacity) < 1)
    errs.capacity = "Capacity must be at least 1.";
  if (!form.type_id)                 errs.type_id     = "Please select a room type.";
  return errs;
}

// ─────────────────────────────────────────────────────────────
// Page
// ─────────────────────────────────────────────────────────────
export default function AdminRoomsCreatePage() {
  const router = useRouter();

  const [types,      setTypes]      = useState<RoomType[]>([]);
  const [buildings,  setBuildings]  = useState<Building[]>([]);
  const [buildingsLoading, setBuildingsLoading] = useState(true);
  const [form,       setForm]       = useState<FormData>({
    room_number: "", building: "", capacity: "", type_id: "", is_available: true,
  });
  const [fieldErrors, setFieldErrors] = useState<FieldErrors>({});
  const [apiError,    setApiError]    = useState<string | null>(null);
  const [loading,     setLoading]     = useState(false);
  const [success,     setSuccess]     = useState(false);

  // Fetch room types on mount
  useEffect(() => {
    api.get<{ data: RoomType[] }>("/admin/room-types")
      .then(res => setTypes(res.data ?? []))
      .catch(() => setTypes([]));

    api.get<{ data: Building[] }>("/admin/buildings")
      .then((res) => setBuildings(res.data ?? []))
      .catch(() => setBuildings([]))
      .finally(() => setBuildingsLoading(false));
  }, []);

  function setField<K extends keyof FormData>(key: K, value: FormData[K]) {
    setForm(p => ({ ...p, [key]: value }));
    setFieldErrors(p => ({ ...p, [key]: undefined }));
    setApiError(null);
  }

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    const errs = validate(form);
    if (Object.keys(errs).length) { setFieldErrors(errs); return; }

    setLoading(true);
    setApiError(null);

    try {
      await api.post("/admin/rooms", {
        room_number:  form.room_number.trim().toUpperCase(),
        building:     form.building.trim(),
        capacity:     Number(form.capacity),
        type_id:      Number(form.type_id),
        is_available: form.is_available,
      });
      setSuccess(true);
      setTimeout(() => router.push("/admin/rooms"), 1200);
    } catch (err: unknown) {
      setApiError(err instanceof Error ? err.message : "Failed to create room.");
    } finally {
      setLoading(false);
    }
  }

  // ── Success state ──────────────────────────────────────────
  if (success) {
    return (
      <AppShell role="admin" userName="Admin Cruz" pageTitle="Create Room">
        <div className="max-w-lg mx-auto animate-fade-in">
          <div className="card card-body flex flex-col items-center text-center gap-4 py-12">
            <div className="w-16 h-16 rounded-full flex items-center justify-center"
              style={{ background: "#e8f5ee" }}>
              <svg width="32" height="32" viewBox="0 0 24 24" fill="none"
                stroke="#22a050" strokeWidth="2.5" strokeLinecap="round">
                <path d="M20 6L9 17l-5-5" />
              </svg>
            </div>
            <div>
              <h2 className="text-[20px] font-bold mb-1" style={{ color: "var(--color-text)" }}>
                Room Created
              </h2>
              <p className="text-[13px]" style={{ color: "var(--color-text-muted)" }}>
                <strong>{form.room_number.toUpperCase()}</strong> has been added to the system.
                Redirecting to rooms list…
              </p>
            </div>
            <Link href="/admin/rooms" className="btn btn-primary">
              Go to Rooms
            </Link>
          </div>
        </div>
      </AppShell>
    );
  }

  // ── Form ──────────────────────────────────────────────────
  const selectedType = types.find(t => String(t.id) === form.type_id);
  const typeStyle    = selectedType ? (TYPE_STYLE[selectedType.name] ?? null) : null;

  return (
    <AppShell role="admin" userName="Admin Cruz" pageTitle="Create Room">
      <div className="max-w-2xl mx-auto animate-fade-in">

        {/* ── Header ── */}
        <div className="flex items-center gap-3 mb-6">
          <Link href="/admin/rooms"
            className="p-2 rounded-lg transition-colors"
            style={{ color: "var(--color-text-secondary)", background: "var(--color-surface-2)" }}>
            <IcoBack />
          </Link>
          <div>
            <h1 className="text-[20px] font-bold" style={{ color: "var(--color-text)" }}>
              Add New Room
            </h1>
            <p className="text-[12.5px]" style={{ color: "var(--color-text-muted)" }}>
              Fill in the details below to add a room to the scheduling system.
            </p>
          </div>
        </div>

        <form onSubmit={handleSubmit} noValidate>

          {/* ── API error ── */}
          {apiError && (
            <div className="flex items-start gap-2.5 px-4 py-3 rounded-xl border mb-5 animate-fade-in"
              style={{ background: "var(--color-error-light)", borderColor: "rgba(217,48,37,.2)", color: "var(--color-error)" }}>
              <span className="shrink-0 mt-0.5"><IcoAlert /></span>
              <p className="text-[13px] leading-snug">{apiError}</p>
            </div>
          )}

          {/* ── Room Details card ── */}
          <div className="card mb-4">
            <div className="px-6 py-4 border-b flex items-center gap-2"
              style={{ borderColor: "var(--color-border)" }}>
              <span style={{ color: "var(--color-primary)" }}><IcoRoom /></span>
              <h2 className="text-[13.5px] font-semibold" style={{ color: "var(--color-text)" }}>
                Room Details
              </h2>
            </div>
            <div className="px-6 py-5 flex flex-col gap-4">

              {/* Room number + Building */}
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div className="form-group">
                  <label htmlFor="room_number" className="form-label">
                    Room Number <span style={{ color: "var(--color-error)" }}>*</span>
                  </label>
                  <div className="input-icon-wrapper">
                    <span className="input-icon-left" style={{ color: "var(--color-text-muted)" }}>
                      <IcoRoom />
                    </span>
                    <input
                      id="room_number"
                      type="text"
                      value={form.room_number}
                      onChange={e => setField("room_number", e.target.value)}
                      placeholder="e.g. CS-101, AVR-2"
                      className="input-has-left-icon"
                      style={fieldErrors.room_number
                        ? { borderColor: "var(--color-error)", boxShadow: "0 0 0 3px rgba(217,48,37,.10)" }
                        : {}}
                    />
                  </div>
                  {fieldErrors.room_number
                    ? <p className="form-error">{fieldErrors.room_number}</p>
                    : <p className="form-hint">Will be stored in uppercase.</p>}
                </div>

                <div className="form-group">
                  <label htmlFor="building" className="form-label">
                    Building <span style={{ color: "var(--color-error)" }}>*</span>
                  </label>
                  <div className="input-icon-wrapper">
                    <span className="input-icon-left" style={{ color: "var(--color-text-muted)" }}>
                      <IcoBldg />
                    </span>
                    <select
                      id="building"
                      value={form.building}
                      onChange={e => setField("building", e.target.value)}
                      className="input-has-left-icon"
                      disabled={buildingsLoading}
                      style={fieldErrors.building
                        ? { borderColor: "var(--color-error)", boxShadow: "0 0 0 3px rgba(217,48,37,.10)" }
                        : {}}
                    >
                      <option value="">{buildingsLoading ? "Loading buildings..." : "Select building..."}</option>
                      {buildings.map((b) => (
                        <option key={b.id} value={b.name}>
                          {b.name}
                        </option>
                      ))}
                    </select>
                  </div>
                  {fieldErrors.building && <p className="form-error">{fieldErrors.building}</p>}
                  {!buildingsLoading && buildings.length === 0 && (
                    <p className="form-error">No buildings found. Add building rows in the `buildings` table first.</p>
                  )}
                </div>
              </div>

              {/* Capacity + Room type */}
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div className="form-group">
                  <label htmlFor="capacity" className="form-label">
                    Capacity <span style={{ color: "var(--color-error)" }}>*</span>
                  </label>
                  <div className="input-icon-wrapper">
                    <span className="input-icon-left" style={{ color: "var(--color-text-muted)" }}>
                      <IcoUsers />
                    </span>
                    <input
                      id="capacity"
                      type="number"
                      min={1}
                      value={form.capacity}
                      onChange={e => setField("capacity", e.target.value)}
                      placeholder="e.g. 40"
                      className="input-has-left-icon"
                      style={fieldErrors.capacity
                        ? { borderColor: "var(--color-error)", boxShadow: "0 0 0 3px rgba(217,48,37,.10)" }
                        : {}}
                    />
                  </div>
                  {fieldErrors.capacity
                    ? <p className="form-error">{fieldErrors.capacity}</p>
                    : <p className="form-hint">Maximum student headcount. Strictly enforced at approval.</p>}
                </div>

                <div className="form-group">
                  <label htmlFor="type_id" className="form-label">
                    Room Type <span style={{ color: "var(--color-error)" }}>*</span>
                  </label>
                  <div className="input-icon-wrapper">
                    <span className="input-icon-left" style={{ color: "var(--color-text-muted)" }}>
                      <IcoTag />
                    </span>
                    <select
                      id="type_id"
                      value={form.type_id}
                      onChange={e => setField("type_id", e.target.value)}
                      className="input-has-left-icon"
                      style={fieldErrors.type_id
                        ? { borderColor: "var(--color-error)", boxShadow: "0 0 0 3px rgba(217,48,37,.10)" }
                        : {}}
                    >
                      <option value="">Select room type…</option>
                      {types.map(t => (
                        <option key={t.id} value={String(t.id)}>{t.name}</option>
                      ))}
                    </select>
                  </div>
                  {fieldErrors.type_id && <p className="form-error">{fieldErrors.type_id}</p>}
                  {/* Selected type badge */}
                  {typeStyle && selectedType && (
                    <div className="mt-1.5 flex items-center gap-1.5">
                      <span className="text-[11px] font-semibold px-2.5 py-0.5 rounded-full"
                        style={{ background: typeStyle.bg, color: typeStyle.color }}>
                        {selectedType.name}
                      </span>
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>

          {/* ── Availability card ── */}
          <div className="card mb-6">
            <div className="px-6 py-4 border-b flex items-center gap-2"
              style={{ borderColor: "var(--color-border)" }}>
              <span style={{ color: "var(--color-primary)" }}><IcoCheck /></span>
              <h2 className="text-[13.5px] font-semibold" style={{ color: "var(--color-text)" }}>
                Availability
              </h2>
            </div>
            <div className="px-6 py-5">
              <label className="flex items-start gap-3 cursor-pointer select-none">
                {/* Toggle */}
                <button
                  type="button"
                  onClick={() => setField("is_available", !form.is_available)}
                  className="relative shrink-0 rounded-full transition-colors duration-200 border-2 mt-0.5"
                  style={{
                    width: "40px", height: "22px",
                    background:   form.is_available ? "var(--color-primary-light)" : "var(--color-border)",
                    borderColor:  form.is_available ? "var(--color-primary-light)" : "var(--color-border)",
                  }}
                  aria-pressed={form.is_available}
                >
                  <span
                    className="absolute top-0.5 w-4 h-4 rounded-full bg-white shadow transition-transform duration-200"
                    style={{ transform: form.is_available ? "translateX(19px)" : "translateX(1px)" }}
                  />
                </button>
                <div>
                  <p className="text-[13.5px] font-semibold" style={{ color: "var(--color-text)" }}>
                    Available for booking
                  </p>
                  <p className="text-[12px] mt-0.5" style={{ color: "var(--color-text-muted)" }}>
                    {form.is_available
                      ? "Instructors can request this room. It will appear in the room browser."
                      : "Room is disabled (e.g. under renovation). Instructors cannot request it."}
                  </p>
                </div>
              </label>

              {!form.is_available && (
                <div className="flex items-start gap-2 mt-3 px-3 py-2.5 rounded-lg"
                  style={{ background: "#fff8e6", color: "#92620a" }}>
                  <span className="shrink-0 mt-0.5"><IcoInfo /></span>
                  <p className="text-[12px] leading-snug">
                    You can re-enable this room at any time from the Room Detail page.
                  </p>
                </div>
              )}
            </div>
          </div>

          {/* ── Preview summary ── */}
          {(form.room_number || form.building || form.capacity || form.type_id) && (
            <div className="card mb-6" style={{ borderColor: "var(--color-primary-light)", borderWidth: "1.5px" }}>
              <div className="px-6 py-4 border-b flex items-center gap-2"
                style={{ borderColor: "var(--color-border)" }}>
                <span style={{ color: "var(--color-primary)" }}><IcoInfo /></span>
                <h2 className="text-[13px] font-semibold" style={{ color: "var(--color-text)" }}>
                  Preview
                </h2>
              </div>
              <div className="px-6 py-4 grid grid-cols-2 sm:grid-cols-4 gap-4">
                {[
                  { label: "Room Number", value: form.room_number ? form.room_number.toUpperCase() : "—"    },
                  { label: "Building",    value: form.building    || "—"                                     },
                  { label: "Capacity",    value: form.capacity    ? `${form.capacity} seats` : "—"          },
                  { label: "Type",        value: selectedType?.name || "—"                                   },
                ].map(f => (
                  <div key={f.label}>
                    <p className="text-[10.5px] font-semibold uppercase tracking-wide"
                      style={{ color: "var(--color-text-muted)" }}>
                      {f.label}
                    </p>
                    <p className="text-[13.5px] font-semibold mt-0.5" style={{ color: "var(--color-text)" }}>
                      {f.value}
                    </p>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* ── Actions ── */}
          <div className="flex items-center gap-3 justify-end">
            <Link
              href="/admin/rooms"
              className="btn btn-ghost text-[13px]"
              style={{ padding: "9px 18px" }}>
              Cancel
            </Link>
            <button
              type="submit"
              disabled={loading}
              className="btn btn-primary flex items-center gap-2 text-[13px]"
              style={{ padding: "9px 20px", opacity: loading ? 0.8 : 1, cursor: loading ? "not-allowed" : "pointer" }}>
              {loading ? <><Spinner /> Creating…</> : <><IcoCheck /> Create Room</>}
            </button>
          </div>

        </form>
      </div>
    </AppShell>
  );
}
